def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    prev_bids = []
    rich_pressure = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            b = prev.get('bid', 0)
            prev_bids.append(b)
            if opp.get('budget', 0) > DAILY_SALARY * 4:
                rich_pressure.append(b)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    rich_high = max(rich_pressure) if rich_pressure else highest_prev

    demand_units = 1
    opponents_demand = 0
    urgent_opponents = 0
    for opp in alive_opponents:
        req = opp.get('water_requirement', WATER_REQ)
        opponents_demand += req
        if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
            urgent_opponents += 1
    total_demand = WATER_REQ + opponents_demand
    scarcity = supply / float(total_demand) if total_demand > 0 else 1.0

    urgency = 0
    if hp <= 2:
        urgency = 3
    elif hp <= 4 or no_water >= 1:
        urgency = 2
    elif hp <= 6:
        urgency = 1

    if not alive_opponents:
        base = DAILY_SALARY * 0.35 if urgency == 0 else DAILY_SALARY * 0.75
        return float(min(budget, base))

    if urgency >= 3:
        target = max(DAILY_SALARY * 1.55, rich_high + 3.0)
    elif urgency == 2:
        target = max(DAILY_SALARY * 1.2, rich_high + 1.5)
    elif urgency == 1:
        if scarcity < 0.32 or urgent_opponents >= 2:
            target = max(DAILY_SALARY * 0.95, highest_prev * 0.9)
        else:
            target = max(DAILY_SALARY * 0.7, highest_prev * 0.65)
    else:
        if scarcity < 0.28 and highest_prev > DAILY_SALARY:
            target = DAILY_SALARY * 0.8
        elif supply >= 22:
            target = DAILY_SALARY * 0.38
        else:
            target = DAILY_SALARY * 0.5

    if day >= 8 and hp > 5 and no_water == 0:
        target *= 0.9

    if budget < DAILY_SALARY * 2 and urgency == 0:
        target = min(target, DAILY_SALARY * 0.45)

    target = min(target, budget)
    if target < 0:
        target = 0.0
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 90
    WATER_REQ = 9
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 80.0

    if my_status['hp'] < 4:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if day_context['supply'] < WATER_REQ * 1.5:
        return min(my_status['budget'], max(avg_prev * 1.05, 95.0))

    return min(my_status['budget'], max(avg_prev * 0.8, 75.0))
